import { createHash } from 'node:crypto';

/**
 * The frontend's src/types/api.ts is a generated copy of src/contracts/api.ts:
 *
 *   // @generated by topflyte-backend `npm run contracts:sync` — DO NOT EDIT.
 *   // Source: topflyte-backend/src/contracts/api.ts · sha256:<hash of the body>
 *   <blank line>
 *   <body = the contract source, verbatim>
 *
 * The frontend has a test that recomputes the hash, so hand edits there fail CI.
 * Line endings are normalised so Windows checkouts (CRLF) hash the same.
 */

export const GENERATED_MARKER = '// @generated by topflyte-backend';

export function normaliseEol(text: string): string {
  return text.replace(/\r\n/g, '\n');
}

export function contractHash(body: string): string {
  return createHash('sha256').update(normaliseEol(body), 'utf8').digest('hex');
}

export function renderGeneratedContract(source: string): string {
  const body = normaliseEol(source);
  return (
    `${GENERATED_MARKER} \`npm run contracts:sync\` — DO NOT EDIT.\n` +
    `// Source: topflyte-backend/src/contracts/api.ts · sha256:${contractHash(body)}\n\n` +
    body
  );
}
